import com.vaadin.flow.component.sidenav.SideNavItem;
import com.vaadin.flow.theme.lumo.LumoUtility;

/**
 * Shared application shell. Renders the clinic logo in the header and the
 * main navigation menu (Home, Find Owners, Veterinarians, Error) as a
 * {@link SideNav} in the drawer, per UC-001.
 */
public class MainLayout extends AppLayout {

    /** Accessible name of the drawer's navigation landmark. */
    public static final String NAV_LABEL = "Main menu";

    public MainLayout() {
        Image logo = new Image("images/petclinic-logo.svg", "PetClinic logo");
        logo.setHeight("40px");

        H1 title = new H1("PetClinic");
        title.addClassNames(LumoUtility.FontSize.LARGE, LumoUtility.Margin.NONE);

        HorizontalLayout header = new HorizontalLayout(
                new DrawerToggle(), logo, title);
        header.setDefaultVerticalComponentAlignment(FlexComponent.Alignment.CENTER);
        header.setWidthFull();
        header.addClassNames(LumoUtility.Padding.Horizontal.MEDIUM);

        addToNavbar(header);

        SideNavItem homeLink = new SideNavItem("Home", WelcomeView.class);
        SideNavItem findOwnersLink = new SideNavItem("Find Owners", "owners/find");
        SideNavItem vetsLink = new SideNavItem("Veterinarians", "vets");
        SideNavItem errorLink = new SideNavItem("Error", CrashView.class);

        SideNav sideNav = new SideNav();
        // The menu shows no visible heading, so the <nav> landmark would reach
        // assistive technology — and accessibility-first test locators —
        // unnamed. SideNav has no setAriaLabel, hence the element-level attribute.
        sideNav.getElement().setAttribute("aria-label", NAV_LABEL);
        sideNav.addItem(homeLink, findOwnersLink, vetsLink, errorLink);

        addToDrawer(sideNav);
    }
}
package ai.unifiedprocess.petclinic.core.ui;

import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.router.ErrorParameter;

/**
 * The one error screen of UC-010. Vaadin picks the error view whose
 * {@code HasErrorParameter} type parameter is closest to the thrown exception,
 * so {@link ApplicationErrorView} and {@link NotFoundErrorView} exist to
 * carry that parameter and the HTTP status that goes with it. Everything the
 * user sees — the shell, the heading, the message, the way home — is here and
 * identical for both (UC-010 BR-003: the message, never a stack trace).
 */
abstract class ErrorShellView extends VerticalLayout {

    private final ErrorPanel panel;

    ErrorShellView() {
        setSizeFull();
        setPadding(false);
        panel = new ErrorPanel();
        add(panel);
    }

    /** Renders the failure and returns the status the browser is told. */
    protected int show(ErrorParameter<? extends Exception> parameter, int httpStatus) {
        panel.setMessage(parameter.hasCustomMessage()
                ? parameter.getCustomMessage()
                : parameter.getException().getMessage());
        return httpStatus;
    }
}
